)} × ${g.widthFeet.roundToInt()} ft",color=Color.White,fontSize=t(15f),fontWeight=FontWeight.Bold)};Spacer(Modifier.height(d(10f)));HeatMap(samples,state.metric,g,fresh,d,t,onMove,Modifier.weight(1f).fillMaxWidth())}};NeonPanel(Modifier.weight(.31f).fillMaxHeight()){if(fresh.isEmpty())Box(Modifier.fillMaxSize(),contentAlignment=Alignment.Center){Text("No fresh sensor readings",color=DashboardTokens.Muted,fontSize=t(16f))}else LazyColumn(Modifier.fillMaxSize().padding(d(10f)),verticalArrangement=Arrangement.spacedBy(d(7f))){items(fresh,key={it.id}){s->ZoneSummary(s,d,t)}}}}}}

