@Composable private fun HeatMap(samples:List<studio.junecity.greenhouse.data.SpatialSample>,metric:Metric,g:GreenhouseConfig,sensors:List<GoveeSensor>,d:(Float)->androidx.compose.ui.unit.Dp,t:(Float)->androidx.compose.ui.unit.TextUnit,onMove:(String,Double,Double)->Unit,modifier:Modifier){BoxWithConstraints(modifier.background(Color(0xFF072529),RoundedCornerShape(d(18f))).border(d(2f),Color.White,RoundedCornerShape(d(18f)))){val cols=32;val rows=16;val values=List(rows){y->List(cols){x->SpatialInterpolator.estimate(samples,(x+.5)*g.lengthFeet/cols,(y+.5)*g.widthFeet/rows)}};val finite=values.flatten().filterNotNull();val min=finite.minOrNull()?:60.0;val max=finite.maxOrNull()?:80.0;Canvas(Modifier.fillMaxSize()){val cw=size.width/cols;val rh=size.height/rows;for(y in 0 until rows)for(x in 0 until cols){val v=values[y][x];drawRect(if(v==null)Color(0xFF0B3134) else heatColor(v,min,max,metric),Offset(x*cw,y*rh),Size(cw+1,rh+1))};for(i in 1 until 8)drawLine(Color.White.copy(alpha=.22f),Offset(size.width*i/8,0f),Offset(size.width*i/8,size.height),1f);for(i in 1 until 4)drawLine(Color.White.copy(alpha=.22f),Offset(0f,size.height*i/4),Offset(size.width,size.height*i/4),1f)};sensors.forEachIndexed{i,s->val stored=g.sensorPositions[s.id]?:SensorPosition(g.lengthFeet*(if(i%2==0).2 else .8),g.widthFeet*(if(i<2).25 else .75));DraggableSensor(s,stored.normalized(g),metric,d,t,maxWidth.value,maxHeight.value){nx,ny->onMove(s.id,nx,ny)}}}}
@Composable private fun DraggableSensor(sensor:GoveeSensor,initial:NormalizedPosition,metric:Metric,d:(Float)->androidx.compose.ui.unit.Dp,t:(Float)->androidx.compose.ui.unit.TextUnit,widthDp:Float,heightDp:Float,onMove:(Double,Double)->Unit){var x by remember(sensor.id,initial.x){mutableDoubleStateOf(initial.x)};var y by remember(sensor.id,initial.y){mutableDoubleStateOf(initial.y)};val density=androidx.compose.ui.platform.LocalDensity.current.density;val value=when(metric){Metric.Temperature->formatTemp(sensor.temperatureF);Metric.Humidity->formatHumidity(sensor.humidityPercent);Metric.Vpd->sensor.vpdKpa?.let{"%.1f".format(it)}?:"—";Metric.DewPoint->formatTemp(sensor.dewPointF)};Column(Modifier.offset{IntOffset((x*widthDp*density-d(42f).toPx()).roundToInt(),(y*heightDp*density-d(42f).toPx()).roundToInt())}.size(d(84f)).background(Color(0xCC082326),CircleShape).border(d(2f),Color.White,CircleShape).pointerInput(sensor.id){detectDragGestures(onDragEnd={onMove(x,y)}){change,drag->change.consume();x=(x+drag.x/(widthDp*density)).coerceIn(.04,.96);y=(y+drag.y/(heightDp*density)).coerceIn(.08,.92)}},horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.Center){Text(sensor.zone.removePrefix("Zone ").let{"S$it"},color=Color.White,fontSize=t(14f),fontWeight=FontWeight.Bold);Text(value,color=Color.White,fontSize=t(16f),fontWeight=FontWeight.Bold);Box(Modifier.size(d(8f)).background(if(sensor.online)DashboardTokens.Green else Color.Gray,CircleShape))}}

@Composable private fun HistoryContent(state:GreenhouseUiState,d:(Float)->androidx.compose.ui.unit.Dp,t:(Float)->androidx.compose.ui.unit.TextUnit,onMetric:(Metric)->Unit){Column(Modifier.fillMaxSize()){Row(Modifier.height(d(72f)),horizontalArrangement=Arrangement.spacedBy(d(18f))){NeonPanel(Modifier.weight(.30f).fillMaxHeight()){Box(Modifier.fillMaxSize(),contentAlignment=Alignment.Center){Text("▣   Last 7 Days⌄",color=Color.White,fontSize=t(19f),fontWeight=FontWeight.Bold)}};Box(Modifier.weight(.70f)){MetricControls(state.metric,d,t,onMetric)}};Spacer(Modifier.height(d(16f)));Row(Modifier.weight(1f),horizontalArrangement=Arrangement.spacedBy(d(14f))){NeonPanel(Modifier.weight(.70f).fillMaxHeight()){Column(Modifier.fillMaxSize().padding(d(22f))){Text("${state.metric.name} History",color=Color.White,fontSize=t(24f),fontWeight=FontWeight.Bold);Spacer(Modifier.height(d(12f)));HistoryChart(state.history,state.metric,d,t,Modifier.weight(1f).fillMaxWidth())}};NeonPanel(Modifier.weight(.30f).fillMaxHeight()){val grouped=state.history.groupBy{it.sensorId};if(grouped.isEmpty())Box(Modifier.fillMaxSize(),contentAlignment=Alignment.Center){Text("No recorded sensors",color=DashboardTokens.Muted,fontSize=t(15f))}else LazyColumn(Modifier.fillMaxSize().padding(d(10f)),verticalArrangement=Arrangement.spacedBy(d(7f))){items(grouped.entries.toList().take(6)){(_,rows)->val latest=rows.maxByOrNull{it.timestampEpochMs};val vals=rows.map{historyMetric(it,state.metric)};Row(Modifier.fillMaxWidth().height(d(76f)).background(Color(0x6607272B),RoundedCornerShape(d(14f))).padding(d(12f)),verticalAlignment=Alignment.CenterVertically){Box(Modifier.width(d(9f)).fillMaxHeight().background(sensorColor(latest?.sensorName?:""),RoundedCornerShape(d(6f))));Spacer(Modifier.width(d(12f)));Column(Modifier.weight(1f)){Text(latest?.sensorName?:"Sensor",color=Color.White,fontSize=t(16f),fontWeight=FontWeight.Bold);Text("Min ${formatMetric(vals.minOrNull(),state.metric)}   Max ${formatMetric(vals.maxOrNull(),state.metric)}",color=DashboardTokens.Muted,fontSize=t(11f))};Text(formatMetric(latest?.let{historyMetric(it,state.metric)},state.metric),color=DashboardTokens.Green,fontSize=t(21f),fontWeight=FontWeight.Bold)}}}}}}}
@Composable private fun HistoryChart(history:List<HistoryReading>,metric:Metric,d:(Float)->androidx.compose.ui.unit.Dp,t:(Float)->androidx.compose.ui.unit.TextUnit,modifier:Modifier){Box(modifier){Canvas(Modifier.fillMaxSize()){val cutoff=System.currentTimeMillis()-7L*24*60*60*1000;val rows=history.filter{it.timestampEpochMs>=cutoff}.sortedBy{it.timestampEpochMs};if(rows.isEmpty()){drawLine(Color(0xFF35646B),Offset(0f,size.height/2),Offset(size.width,size.height/2),2f);return@Canvas};val values=rows.map{historyMetric(it,metric)};val padding=if(metric==Metric.Vpd).2 else 2.0;val min=(values.minOrNull()?:0.0)-padding;val max=(values.maxOrNull()?:1.0)+padding;val start=rows.first().timestampEpochMs;val end=rows.last().timestampEpochMs.coerceAtLeast(start+1);repeat(5){i->val y=size.height*i/4;drawLine(Color(0xFF35646B),Offset(0f,y),Offset(size.width,y),1f)};rows.groupBy{it.sensorId}.values.forEachIndexed{i,series->val p=Path();series.forEachIndexed{j,r->val x=((r.timestampEpochMs-start).toFloat()/(end-start))*size.width;val v=historyMetric(r,metric);val y=size.height-((v-min)/(max-min)*size.height).toFloat();if(j==0)p.moveTo(x,y)else p.lineTo(x,y)};drawPath(p,sensorColor(i),style=Stroke(5f,cap=StrokeCap.Round))}};if(history.isEmpty())Text("No history yet · readings appear after the first sensor sync",color=DashboardTokens.Muted,fontSize=t(15f),modifier=Modifier.align(Alignment.Center))}}

@Composable private fun CameraContent(state:GreenhouseUiState,d:(Float)->androidx.compose.ui.unit.Dp,t:(Float)->androidx.compose.ui.unit.TextUnit){
    val context=LocalContext.current
    var selectedTab by remember{mutableIntStateOf(0)}
    var permissionGranted by remember{mutableStateOf(ContextCompat.checkSelfPermission(context,Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED)}
    var cameraActive by remember{mutableStateOf(false)}
    var cameraMessage by remember{mutableStateOf<String?>(null)}
    val permissionLauncher=rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()){permissionGranted=it;cameraMessage=if(it)null else "Camera permission denied"}
    LaunchedEffect(state.preferences.cameraMode){if(state.preferences.cameraMode==CameraMode.CameraServer&&!permissionGranted)permissionLauncher.launch(Manifest.permission.CAMERA)}
    Column(Modifier.fillMaxSize()){
        CameraControls(selectedTab,d,t){selectedTab=it}
        Spacer(Modifier.height(d(16f)))
        Row(Modifier.weight(1f),horizontalArrangement=Arrangement.spacedBy(d(16f))){
            NeonPanel(Modifier.weight(.70f).fillMaxHeight()){
                when(selectedTab){
                    0->if(state.preferences.cameraMode==CameraMode.ViewerClient)CameraMessage("Secure viewer mode","Waiting for an authenticated streaming endpoint. This phone will never publish its camera in Viewer Client mode.",d,t) else if(permissionGranted)LiveCameraPreview(d,t){active,message->cameraActive=active;cameraMessage=message}else CameraMessage("Camera permission required","Allow camera access to open the front camera.",d,t){permissionLauncher.launch(Manifest.permission.CAMERA)}
                    1->CameraMessage("No recordings yet","Playback will show saved camera recordings when recording storage is configured.",d,t)
                    2->CameraMessage("Timelapse not configured","Timelapse capture needs an interval and storage destination.",d,t)
                    else->CameraMessage(if(state.preferences.cameraMode==CameraMode.CameraServer)"Greenhouse Server" else "Viewer Client",if(state.preferences.cameraMode==CameraMode.CameraServer)"This phone may publish its front camera after secure streaming is configured." else "This phone is view-only and will not request camera access.",d,t)
                }
            }
            NeonPanel(Modifier.weight(.30f).fillMaxHeight()){
                Column(Modifier.padding(d(18f))){
                    Text(listOf(if(state.preferences.cameraMode==CameraMode.CameraServer)"Greenhouse Server" else "Viewer Client","Playback","Timelapse","Camera settings")[selectedTab],color=Color.White,fontSize=t(21f),fontWeight=FontWeight.Bold)
                    Spacer(Modifier.height(d(12f)))
                    val status=when(selectedTab){0->if(state.preferences.cameraMode==CameraMode.ViewerClient)"View-only · endpoint required" else when{!permissionGranted->"Permission required";cameraActive->"Front camera active";cameraMessage!=null->cameraMessage!!;else->"Starting front camera…"};1->"No saved recordings";2->"Not configured";else->if(state.preferences.cameraMode==CameraMode.CameraServer)"Publish-only role" else "View-only role"}
                    Text(status,color=if(cameraActive&&selectedTab==0)DashboardTokens.Green else Color(0xFFFFB23F),fontSize=t(18f))
                    Text("Each button now opens its own camera section. Remote viewing and stored media still require a streaming and storage backend.",color=DashboardTokens.Muted,fontSize=t(13f),modifier=Modifier.padding(top=d(12f)))
                }
            }
        }
    }
}
